public final class PlayerActivity extends AppScreen{private VideoView video;protected void render(){String id=n(getIntent().getStringExtra("id")),t=n(getIntent().getStringExtra("title")),provider=n(getIntent().getStringExtra("provider"));int ep=getIntent().getIntExtra("episode",1);String key="progress_"+id+"_"+ep;title((t.length()==0?"Anime":t)+" · Episode "+ep);MediaProvider p=findProvider(provider);if(p==null||!p.supportsPlayback()){subtitle("This source does not provide a compatible playback resolver. Choose a playable provider from Browse.");nav();return;}subtitle("Resolving provider media…");video=new VideoView(this);video.setMinimumHeight(dp(220));MediaController controls=new MediaController(this);controls.setAnchorView(video);video.setMediaController(controls);body.addView(video,new LinearLayout.LayoutParams(-1,dp(240)));new Thread(()->{try{String url=p.resolveMediaUrl(id,ep);runOnUiThread(()->start(url,key,t,ep));}catch(Exception e){runOnUiThread(()->subtitle("Playback failed: "+e.getMessage()));}}).start();nav();}private void start(String url,String key,String t,int ep){if(url==null||!url.startsWith("https://")){subtitle("Playback failed: provider returned a non-HTTPS media URL.");return;}try{video.setVideoURI(Uri.parse(url));int resume=store.number(key);video.setOnPreparedListener(mp->{if(resume>0)video.seekTo(resume*1000);video.start();});video.setOnCompletionListener(mp->{store.number(key,0);store.putText("last_episode",t+" · Episode "+ep);});video.setOnErrorListener((mp,what,extra)->{subtitle("Android could not play this media format. Try another provider.");return true;});}catch(Exception e){subtitle("Playback failed: "+e.getMessage());}}@Override protected void onPause(){super.onPause();if(video!=null){int ms=video.getCurrentPosition();if(ms>0){String id=n(getIntent().getStringExtra("id"));int ep=getIntent().getIntExtra("episode",1);store.number("progress_"+id+"_"+ep,ms/1000);store.putText("last_episode",n(getIntent().getStringExtra("title"))+" · Episode "+ep);}}}private MediaProvider findProvider(String id){MediaProvider p=BuiltInProviderCatalog.find(id);if(p!=null)return p;ExtensionRecord x=new ExtensionManager(this).find(id);return x==null?null:new RepositoryMediaProvider(x);}private String n(String s){return s==null?"":s;}}
